INSERT INTO pages (slug, title, content, published)
VALUES ('about', 'About — ReplyPilot', '[{"type": "h2", "text": "What we do"}, {"type": "p", "text": "We build AI sales agents and workflow automations that help small and growing businesses respond faster, capture more leads, and save hours every week. That includes:"}, {"type": "ul", "items": ["WhatsApp DM automation that answers customers instantly", "Instagram DM automation for bookings and enquiries", "Website chatbots that qualify and capture leads 24/7", "E-commerce store assistants that reduce cart abandonment", "Custom n8n workflow automations for repetitive tasks"]}, {"type": "h2", "text": "How we work"}, {"type": "p", "text": "Every build starts with understanding your business \u2014 how you get customers today, where leads slip through, and what eats your time. Then we design, build, and launch a custom AI agent for your business, usually within 48 hours. You see a working demo before you pay anything beyond the upfront split."}, {"type": "h2", "text": "Why ReplyPilot"}, {"type": "p", "text": "Most AI tools are generic. We build for one business at a time \u2014 your services, your tone, your customers. No templates pretending to be custom. And we stay after launch: the monthly care plan keeps your agent improving as your business grows."}, {"type": "h2", "text": "Get in touch"}, {"type": "p", "text": "Want to see what an AI agent could do for your business? Contact us or try a live demo \u2014 it takes two minutes."}]'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, published = TRUE;

INSERT INTO pages (slug, title, content, published)
VALUES ('contact', 'Contact — ReplyPilot', '[{"type": "h2", "text": "Email"}, {"type": "p", "text": "muhammadtauseef714@gmail.com"}, {"type": "h2", "text": "What to include"}, {"type": "p", "text": "Tell us a little about your business and what you''d like to automate \u2014 for example:"}, {"type": "ul", "items": ["What kind of business you run", "Where you lose leads today (missed DMs? slow replies?)", "Which channel matters most (WhatsApp, Instagram, website)"]}, {"type": "h2", "text": "Prefer to explore first?"}, {"type": "p", "text": "Try a live demo, read the blog, or watch how the demos work \u2014 no signup needed to look around."}]'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, published = TRUE;

INSERT INTO pages (slug, title, content, published)
VALUES ('faq', 'FAQ — AI Automation Questions Answered | ReplyPilot', '[{"type": "h2", "text": "What is an AI sales agent?"}, {"type": "p", "text": "An AI sales agent is a smart chatbot that talks to your customers on WhatsApp, Instagram, or your website. It answers questions, books appointments, and captures leads \u2014 even at 2 AM when you''re asleep. Think of it as a super-helpful employee who never takes a day off."}, {"type": "h2", "text": "How does WhatsApp automation work?"}, {"type": "p", "text": "When a customer messages your business on WhatsApp, the AI reads the message and replies instantly \u2014 just like a real person would. It can share prices, book appointments, answer common questions, and send the details to you. You only step in when a human touch is needed."}, {"type": "h2", "text": "Do I need technical skills to use it?"}, {"type": "p", "text": "No. We build everything for you. You just tell us about your business \u2014 your services, prices, and common questions \u2014 and we set up the AI agent. Most businesses are live within 48 hours."}, {"type": "h2", "text": "Will customers know they''re talking to AI?"}, {"type": "p", "text": "The AI talks naturally, like a friendly team member. But we''re always honest \u2014 if a customer asks, the agent says it''s an AI assistant. Most customers care about getting quick, helpful answers, not who''s typing them."}, {"type": "h2", "text": "What happens if the AI can''t answer something?"}, {"type": "p", "text": "The AI is trained on your business, so it handles most questions. For anything tricky, it politely hands the conversation to you with a summary \u2014 so you jump in already knowing the full context."}, {"type": "h2", "text": "Can it work on Instagram too?"}, {"type": "p", "text": "Yes. The same AI can handle Instagram DMs \u2014 replying to enquiries, booking appointments, and answering FAQs. Many businesses use it on WhatsApp, Instagram, and their website all at once."}, {"type": "h2", "text": "How much does it cost?"}, {"type": "p", "text": "Pricing is shared after you create a free account and log in. We keep it simple: a one-time build fee and a monthly care plan that keeps your agent improving."}, {"type": "h2", "text": "How long does setup take?"}, {"type": "p", "text": "Most builds go live within 48 hours. We study your business, build the agent, test it with you, and then launch. You''ll see a working demo before anything goes live."}, {"type": "h2", "text": "What if I want changes later?"}, {"type": "p", "text": "That''s what the monthly care plan is for. As your business grows \u2014 new services, new prices, new questions \u2014 we update your agent so it always stays accurate."}, {"type": "h2", "text": "Is my customer data safe?"}, {"type": "p", "text": "Yes. Your data is stored securely and never sold or shared. You own your data \u2014 your customers, your conversations, your business information."}]'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, published = TRUE;

INSERT INTO pages (slug, title, content, published)
VALUES ('privacy', 'Privacy Policy — ReplyPilot', '[{"type": "p", "text": "Last updated: October 14, 2026"}, {"type": "h2", "text": "Who we are"}, {"type": "p", "text": "ReplyPilot is an AI automation studio run by Muhammad Tauseef. This policy explains what data this website collects, why, and how it is handled. If you have questions, email muhammadtauseef714@gmail.com."}, {"type": "h2", "text": "Data we collect"}, {"type": "ul", "items": ["Contact form: your name, email address, business type, and anything you write in the message field.", "On-site AI chat: the messages you send to the chat assistant. If you share your name and email address or phone number and show interest in a demo or callback, the assistant can save those details as a lead. If you ask to book a demo, it saves your name, email address, phone number, and chosen time slot as a booking.", "Chat transcripts: the recent messages from a chat session (the last 13 messages) are stored so enquiries can be reviewed.", "Account data: if you create an account, your email address and the enquiries tied to it. If you sign in with Google, Google shares your name, email address, and profile picture to create your account.", "Usage data: pages visited, measured with Google Analytics only after you accept cookies (see Cookies below).", "Preferences stored in your own browser: your dark or light theme choice, and your cookie consent choice. These stay on your device."]}, {"type": "h2", "text": "How we use your data"}, {"type": "ul", "items": ["To reply to your enquiry or demo request.", "To create and manage your account and provide the services you asked for.", "To improve the website, using aggregated analytics.", "We never sell, rent, or share your personal data with anyone for their own marketing.", "We never send marketing emails you did not ask for."]}, {"type": "h2", "text": "Where your data lives"}, {"type": "p", "text": "Form submissions, leads, bookings, chat transcripts, and account data are stored in a Supabase (PostgreSQL) database with row-level security, so only authorised access can read them. Passwords are handled entirely by Supabase Auth and are never stored in plain text on this site. The website is hosted on Vercel."}, {"type": "h2", "text": "Third-party services"}, {"type": "ul", "items": ["Supabase: database, authentication, and data storage for the services above.", "Google Gemini: the on-site chat assistant is powered by Google Gemini. Messages you send in chat are processed by Google''s API to generate replies, under Google''s own terms. We do not use your chat messages for advertising.", "Google Analytics: measures site usage only after you accept cookies (see Cookies below).", "Vercel: hosts this website."]}, {"type": "h2", "text": "Cookies"}, {"type": "ul", "items": ["Theme preference: your dark or light theme choice, stored only in your browser (localStorage). It never leaves your device.", "Cookie consent choice: your Accept or Reject choice, stored only in your browser (localStorage).", "Authentication: if you sign in, Supabase Auth sets session cookies to keep you signed in.", "Google Analytics (GA4, measurement ID G-1QP894DHB3): only runs if you click Accept in the cookie banner. Before that, Google Consent Mode keeps analytics storage, advertising storage, advertising user data, and advertising personalisation denied. If you click Reject, they stay denied.", "You can change your choice at any time by clearing this site''s data in your browser settings; the banner will appear again."]}, {"type": "h2", "text": "Advertising"}, {"type": "p", "text": "This site does not currently show advertisements. In the future, advertising may be shown through Google AdSense. If that happens, Google may use cookies to serve and measure ads, including advertising storage and personalisation, subject to the consent choice you make in the cookie banner. This section will be updated if advertising goes live."}, {"type": "h2", "text": "Data retention"}, {"type": "p", "text": "We keep your data only as long as it is needed for the purpose it was collected for: to respond to your enquiry, to manage your account, or to operate this website. There is no fixed retention period in the site''s code; when data is no longer needed, it is deleted. You can ask for earlier deletion at any time (see Your rights)."}, {"type": "h2", "text": "Your rights"}, {"type": "p", "text": "You can ask at any time to see, correct, or delete the personal data we hold about you. Just email muhammadtauseef714@gmail.com and it will be handled personally. There is no data protection officer and no automated decision-making on this site."}, {"type": "h2", "text": "Changes"}, {"type": "p", "text": "This policy may be updated occasionally; the date at the top shows the latest version. Continued use of the site after changes means you accept the updated policy."}]'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, published = TRUE;

INSERT INTO pages (slug, title, content, published)
VALUES ('terms', 'Terms of Service — ReplyPilot', '[{"type": "p", "text": "Last updated: October 14, 2026"}, {"type": "h2", "text": "Using this website"}, {"type": "p", "text": "By using this site you agree to these terms. ReplyPilot is an AI automation studio operated by Muhammad Tauseef. If you do not agree, please do not use the site."}, {"type": "h2", "text": "The AI assistant"}, {"type": "p", "text": "The on-site chat assistant answers questions about ReplyPilot''s services. It can save your contact details as a lead or book a demo slot if you ask it to. It does not give legal, financial, or medical advice, and while it tries to be accurate, you should confirm important details by email at muhammadtauseef714@gmail.com."}, {"type": "h2", "text": "Demos"}, {"type": "p", "text": "The demo businesses and demo conversations shown on this site are fictional samples that show what ReplyPilot can build. They are not real clients, real results, or performance claims."}, {"type": "h2", "text": "Services and pricing"}, {"type": "ul", "items": ["Setup: $249 one-time per AI agent, with 50% ($125) due upfront and 50% ($124) on go-live.", "Ongoing care: $99/month for hosting, updates, and support, cancellable anytime.", "Delivery: first build targeted within 48 hours of the upfront payment; you approve before go-live.", "Risk reversal: the second 50% is only due once the agent is live and working as agreed."]}, {"type": "p", "text": "Exact scope, timelines, and any third-party costs (for example WhatsApp or platform fees, paid directly by the client to those providers) are confirmed in writing before work starts. Your agent may also use third-party services that bill you directly, such as AI model API usage and WhatsApp Business API conversation charges; those are explained before you commit."}, {"type": "h2", "text": "Demo bookings"}, {"type": "p", "text": "Demo calls booked through the site are 30 minutes. A booking is stored as pending until confirmed. If a slot is taken before your booking is saved, you will be offered another time."}, {"type": "h2", "text": "Acceptable use"}, {"type": "ul", "items": ["Do not abuse the contact form, chat, or booking tools.", "Do not attempt to break, overload, or bypass this site''s security.", "Do not use the demos or content here to misrepresent ReplyPilot''s work as your own."]}, {"type": "h2", "text": "Intellectual property"}, {"type": "p", "text": "The content on this site, including text, images, videos, and demos, belongs to ReplyPilot. You may read and share links to it, but you may not copy, republish, or claim it as your own without permission."}, {"type": "h2", "text": "Liability"}, {"type": "p", "text": "This site and its demos are provided as is. To the extent allowed by law, ReplyPilot is not liable for indirect or consequential losses from using the site. Nothing here limits rights you have under applicable consumer law."}, {"type": "h2", "text": "Changes"}, {"type": "p", "text": "These terms may be updated occasionally; the date at the top shows the latest version. Continued use of the site after changes means you accept them."}, {"type": "h2", "text": "Contact"}, {"type": "p", "text": "Questions about these terms: email muhammadtauseef714@gmail.com."}]'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, published = TRUE;

INSERT INTO pages (slug, title, content, published)
VALUES ('disclaimer', 'Disclaimer | ReplyPilot', '[{"type": "p", "text": "Last updated: October 8, 2026"}, {"type": "h2", "text": "General information"}, {"type": "p", "text": "The content on ReplyPilot \u2014 including blog articles, guides, demo videos, and AI chat responses \u2014 is provided for general information and educational purposes only. While we work hard to keep everything accurate and helpful, we make no guarantees about completeness, reliability, or suitability for your specific situation."}, {"type": "h2", "text": "No professional advice"}, {"type": "p", "text": "Nothing on this website constitutes legal, financial, or professional business advice. Always consult a qualified professional before making business decisions based on anything you read here."}, {"type": "h2", "text": "AI-generated assistance"}, {"type": "p", "text": "Some content on this site is created with the assistance of AI tools and reviewed by humans before publishing. Demo conversations are illustrative examples, not records of real client interactions."}, {"type": "h2", "text": "Advertising disclosure"}, {"type": "p", "text": "This website may display third-party advertisements (including Google AdSense). We do not control the content of these ads, and their appearance here is not an endorsement of the advertised products or services."}, {"type": "h2", "text": "External links"}, {"type": "p", "text": "We link to external websites we find useful or trustworthy. We are not responsible for the content, accuracy, or practices of those sites."}, {"type": "h2", "text": "Results vary"}, {"type": "p", "text": "Any discussion of automation benefits or business outcomes is illustrative. Individual results depend on many factors, and we do not promise specific results."}, {"type": "h2", "text": "Contact"}, {"type": "p", "text": "Questions about this disclaimer: contact us."}]'::jsonb, TRUE)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, published = TRUE;

